    if(name==='close-process'){$('process-panel').open=false;return true;}
    if(name==='dock-tab'){this.dock(b.dataset.tab);return true;}
    if(name==='logs'){this.dock('logs');return true;}
    if(name==='scene-home'){scrollTo({top:0,behavior:'smooth'});return true;}
    if(name==='host-phase'){this.ui.hooks.act('phase');return true;}
